import{_ as t,o as a,c as o,a0 as i}from"./chunks/framework.DYS8d9tm.js";const g=JSON.parse('{"title":"🚀 System Deployment & Hosting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/deployment.md","filePath":"deployment/deployment.md"}'),n={name:"deployment/deployment.md"};function s(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="🚀-system-deployment-hosting-guide" tabindex="-1">🚀 System Deployment &amp; Hosting Guide <a class="header-anchor" href="#🚀-system-deployment-hosting-guide" aria-label="Permalink to &quot;🚀 System Deployment &amp; Hosting Guide&quot;">​</a></h1><p>WealthFam is a sophisticated, containerized microservice ecosystem. To maintain the highest standards of data integrity and privacy (the <strong>Sovereign Circle</strong> model), we have refined our deployment pathways.</p><hr><h2 id="🏛️-deployment-strategy" tabindex="-1">🏛️ Deployment Strategy <a class="header-anchor" href="#🏛️-deployment-strategy" aria-label="Permalink to &quot;🏛️ Deployment Strategy&quot;">​</a></h2><p>WealthFam is built for <strong>privacy-first local hosting</strong>. We provide an official demo for exploration, but for personal use, local orchestration is the mandatory path until our SaaS offering is launched.</p><h3 id="_1-🌐-official-live-demo" tabindex="-1">1. 🌐 Official Live Demo <a class="header-anchor" href="#_1-🌐-official-live-demo" aria-label="Permalink to &quot;1. 🌐 Official Live Demo&quot;">​</a></h3><p>The only authorized cloud instance of WealthFam is hosted on Render. This instance is for evaluation purposes.</p><ul><li><strong>Demo Instance:</strong> <a href="https://wealthfam.onrender.com" target="_blank" rel="noreferrer">https://wealthfam.onrender.com</a></li><li><strong>Deployment Status:</strong> 🟢 Operational (Render Free Tier)</li><li><strong>Test Credentials:</strong><ul><li>Username: <code>demo@demo.com</code></li><li>Password: <code>demo123</code></li></ul></li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>The demo database is ephemeral and resets periodically. Do not input real sensitive financial data into the demo instance.</p></div><h3 id="_2-🐳-local-hosting-docker" tabindex="-1">2. 🐳 Local Hosting (Docker) <a class="header-anchor" href="#_2-🐳-local-hosting-docker" aria-label="Permalink to &quot;2. 🐳 Local Hosting (Docker)&quot;">​</a></h3><p>For your personal data, we support local hosting via Docker. This ensures your data never leaves your hardware.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Pull the official orchestration stack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/WealthFam/Infra.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Infra/docker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Configure your environment (Optional)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Edit .env to set your GEMINI_API_KEY for AI features</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Launch the ecosystem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p><strong>Hardware Recommendation:</strong></p><ul><li><strong>Entry</strong>: Raspberry Pi 4 (4GB+)</li><li><strong>Optimal</strong>: Dedicated NAS or Home Server (8GB+ RAM, SSD)</li></ul><hr><h2 id="📅-roadmap-managed-hosting-saas" tabindex="-1">📅 Roadmap: Managed Hosting (SaaS) <a class="header-anchor" href="#📅-roadmap-managed-hosting-saas" aria-label="Permalink to &quot;📅 Roadmap: Managed Hosting (SaaS)&quot;">​</a></h2><p>We recognize that not every user wants to maintain their own hardware. We are in the final stages of architecting the <strong>WealthFam Cloud (SaaS)</strong>.</p><ul><li><strong>Status</strong>: 🛠️ In Development (Alpha)</li><li><strong>Features</strong>: <ul><li>Automated Backups</li><li>Managed Security Updates</li><li>100% Privacy via Encrypted Storage Volumes (PostgreSQL/DuckDB)</li><li>Multi-tenant isolation</li></ul></li></ul><hr><h2 id="⚙️-core-configuration" tabindex="-1">⚙️ Core Configuration <a class="header-anchor" href="#⚙️-core-configuration" aria-label="Permalink to &quot;⚙️ Core Configuration&quot;">​</a></h2><p>Whether running locally or in development, the environment is controlled via these primary variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td><code>postgresql://postgres:postgres@localhost:5432/wealthfam</code></td><td>High-performance PostgreSQL database URL</td></tr><tr><td><code>PARSER_DATABASE_URL</code></td><td><code>duckdb:////data/ingestion_engine_parser.duckdb</code></td><td>Ingestion parser regex matching rules &amp; logs</td></tr><tr><td><code>TELEMETRY_DATABASE_URL</code></td><td><code>duckdb:////data/telemetry.duckdb</code></td><td>Admin telemetry timeseries, scrubbed logs &amp; parser templates</td></tr><tr><td><code>LOGOS_STORAGE_PATH</code></td><td><code>/data/logos</code></td><td>Individual brand logo image files managed by Admin Console</td></tr><tr><td><code>ADMIN_USERNAME</code> / <code>ADMIN_PASSWORD</code></td><td><code>admin</code> / <code>admin123</code></td><td>Initial bootstrap credentials for <code>Admin-Web</code> (Port 8080)</td></tr><tr><td><code>ADMIN_SECRET_KEY</code></td><td>Auto-generated</td><td>Independent JWT signing secret for Admin Console</td></tr><tr><td><code>GEMINI_API_KEY</code></td><td>-</td><td>AI-powered transaction Precision analysis</td></tr><tr><td><code>SECRET_KEY</code></td><td>Auto-generated</td><td>JWT &amp; Session security</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>INFO</code></td><td>System observability depth</td></tr></tbody></table><hr><h2 id="📱-mobile-connectivity" tabindex="-1">📱 Mobile Connectivity <a class="header-anchor" href="#📱-mobile-connectivity" aria-label="Permalink to &quot;📱 Mobile Connectivity&quot;">​</a></h2><p>To connect your mobile device to your local instance:</p><ol><li>Ensure your phone is on the same network or you have a secure VPN/Tunnel (e.g., Tailscale).</li><li>Open <strong>WealthFam Mobile</strong> → <strong>Settings</strong>.</li><li>Point the URL to your local server IP (e.g., <code>http://192.168.1.100:80</code>).</li><li>Login with your local account.</li></ol><hr><h2 id="🆘-technical-support" tabindex="-1">🆘 Technical Support <a class="header-anchor" href="#🆘-technical-support" aria-label="Permalink to &quot;🆘 Technical Support&quot;">​</a></h2><p>If you encounter orchestration issues:</p><ul><li><strong><a href="https://wealthfam.github.io/docs" target="_blank" rel="noreferrer">Documentation Hub</a></strong></li><li><strong><a href="https://github.com/WealthFam/Infra" target="_blank" rel="noreferrer">GitHub Infrastructure Repository</a></strong></li><li><strong>Discord Community</strong>: <a href="https://discord.gg/wealthfam" target="_blank" rel="noreferrer">Join the Precision Lab</a></li></ul><hr><div align="center"> *Built for Privacy · Powered by AI · Managed by You* *Made with ❤️ by WGLabz* </div>`,32)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
